"""Baked US-states inline-SVG geometry + facility-point projection (R8.5, KTD5).

Static, license-clean map geometry for the Explore Watchlist Map. Source: **US
Census Bureau Cartographic Boundary Files, 2020, states, 1:5,000,000**
(``cb_2020_us_state_5m``) — a work of the US federal government, **public
domain** (17 U.S.C. § 105); no attribution legally required (citing "US
Census Bureau" is good practice). The shapefile (NAD83 geographic, EPSG:4269 —
plain decimal-degree lon/lat) was converted **offline at author time** (stdlib
struct-parse + Ramer-Douglas-Peucker simplification, epsilon 1.6 px) to the
48-states-plus-DC ``<path>`` set below; nothing here fetches or de-projects at
runtime, so the stdlib-only backend rule is not breached (the UI layer merely
embeds this static asset).

The forward projection ``project(lon, lat)`` is the EXACT plain linear
equirectangular transform the geometry was baked with (see KTD5 ``projection.md``):
a pure two-multiply-add map on each axis, no trig, so a facility's raw lat/long
registers against these paths with zero external library.

Limitation: **continental US + DC only.** Alaska, Hawaii, and territories are
excluded (AK crosses the antimeridian; both AK/HI sit far outside the bounds).
``project_or_none`` returns None for a point outside the continental bounding
box so an AK/HI/offshore facility never mis-projects onto a wrong state.
"""

# viewBox for the baked geometry; every path d-string and every projected
# facility point lives in this 960x600 user-unit space.
VIEWBOX = "0 0 960 600"
SVG_W, SVG_H = 960, 600

# Continental-US extent the geometry was baked against (small pad included).
LON_MIN, LON_MAX = -125.0, -66.9
LAT_MIN, LAT_MAX = 24.4, 49.5


def project(lon, lat):
    """Forward-project (lon, lat) decimal degrees to (x, y) in the 960x600
    viewBox — the EXACT KTD5 linear equirectangular formula. y is flipped so
    north maps to a smaller y. No bounds check (see project_or_none)."""
    x = (lon - LON_MIN) / (LON_MAX - LON_MIN) * SVG_W
    y = (LAT_MAX - lat) / (LAT_MAX - LAT_MIN) * SVG_H
    return x, y


def in_continental_bounds(lon, lat):
    """True when (lon, lat) falls inside the continental-US bounding box the
    geometry covers. AK/HI/territories/offshore points fall outside."""
    return (lon is not None and lat is not None
            and LON_MIN <= lon <= LON_MAX and LAT_MIN <= lat <= LAT_MAX)


def project_or_none(lon, lat):
    """project() when the point is inside the continental bounds, else None so
    an off-map (AK/HI/territory/offshore) facility is omitted, never projected
    onto a wrong state."""
    if not in_continental_bounds(lon, lat):
        return None
    return project(lon, lat)


